67	fn generate_group_code(category: &str, group: &str) -> Result<TokenStream> {
68	    // Use CARGO_MANIFEST_DIR to get the base path since proc_macro::Span::source_file
69	    // is not available on stable Rust
70	    let manifest_dir = std::env::var("CARGO_MANIFEST_DIR").context("CARGO_MANIFEST_DIR not set")?;
71	    let base_path = Utf8PathBuf::from(manifest_dir).join("src").join(category);
72	
73	    // Discover all rules in the group directory
74	    let group_dir = base_path.join(group);
75	    let mut rules = BTreeMap::new();
76	
77	    for entry in std::fs::read_dir(&group_dir)
78	        .with_context(|| format!("Failed to read directory: {}", group_dir))?
79	    {
80	        let entry = entry?.path();
81	
82	        // Check if it's a file and has .rs extension
83	        if !entry.is_file() || entry.extension().and_then(|e| e.to_str()) != Some("rs") {
84	            continue;
85	        }
86	
87	        let file_stem = entry
88	            .file_stem()
89	            .context("path has no file name")?
90	            .to_str()
91	            .context("could not convert file name to string")?;
92	
93	        // Skip mod.rs files
94	        if file_stem == "mod" {
95	            continue;
96	        }
97	
98	        let file_name = file_stem;
99	
100	        let rule_type = Case::Pascal.convert(file_name);
101	
102	        let key = rule_type.clone();
103	        let module_name = format_ident!("{}", file_name);
104	        let rule_type = format_ident!("{}", rule_type);
105	
106	        rules.insert(
107	            key,
108	            (
109	                quote! {
110	                    pub mod #module_name;
111	                },
112	                quote! {
113	                    self::#module_name::#rule_type
114	                },
115	            ),
116	        );
117	    }
118	
119	    if rules.is_empty() {
120	        bail!("No rules found in directory: {}", group_dir);
121	    }
122	
123	    let group_name = format_ident!("{}", Case::Pascal.convert(group));
124	
125	    let (rule_imports, rule_names): (Vec<_>, Vec<_>) = rules.into_values().unzip();
126	
127	    let (import_macro, use_macro) = match category {
128	        "lint" => (
129	            quote!(
130	                use biome_analyze::declare_lint_group
131	            ),
132	            quote!(declare_lint_group),
133	        ),
134	        "assist" => (
135	            quote!(
136	                use biome_analyze::declare_assist_group
137	            ),
138	            quote!(declare_assist_group),
139	        ),
140	        "syntax" => (
141	            quote!(
142	                use biome_analyze::declare_syntax_group
143	            ),
144	            quote!(declare_syntax_group),
145	        ),
146	        _ => bail!("Category not supported: {}", category),
147	    };
148	
149	    let tokens = quote! {
150	        #import_macro;
151	
152	        #( #rule_imports )*
153	
154	
155	        #use_macro! {
156	            pub #group_name {
157	                name: #group,
158	                 rules: [
159	                    #( #rule_names,  )*
160	                 ]
161	            }
162	        }
163	    };
164	
165	    // Format the code using prettyplease since we can't call rustfmt in proc macros
166	    let formatted = format_code(tokens)?;
167	
168	    // Parse the formatted string back into a TokenStream
169	    // We need to go through proc_macro2::TokenStream first, then convert to proc_macro::TokenStream
170	    let token_stream = formatted
171	        .parse::<proc_macro2::TokenStream>()
172	        .map_err(|e| anyhow::anyhow!("Failed to parse formatted code as TokenStream: {}", e))?;
173	
174	    Ok(token_stream.into())
175	}
